import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation that uses a bit array to probabilistically 
    determine whether an item is in a set. It employs multiple hash functions 
    based on the expected number of items and desired false positive rate to 
    minimize collisions and optimize space.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        """
        Initializes the Bloom Filter with a specific size and number of hash functions.

        :param expected_items: The expected number of items to be stored in the filter.
        :param false_positive_rate: The acceptable false positive rate.
        """
        if false_positive_rate <= 0 or false_positive_rate >= 1:
            raise ValueError("False positive rate must be in (0, 1)")

        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        self.size = self._optimal_size()
        self.hash_count = self._optimal_hash_count()

        self.bit_array = [0] * self.size

    def _optimal_size(self) -> int:
        """Calculates the optimal size of the bit array."""
        return int(- (self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _optimal_hash_count(self) -> int:
        """Calculates the optimal number of hash functions to use."""
        return int((self.size / self.expected_items) * math.log(2))

    def _hashes(self, item: str) -> list:
        """Generates multiple hashes for an item."""
        return [int(hashlib.md5((item + str(i)).encode('utf-8')).hexdigest(), 16) % self.size
                   for i in range(self.hash_count)]

    def add(self, item: str) -> None:
        """Adds an item to the Bloom Filter."""
        for hash_value in self._hashes(item):
            self.bit_array[hash_value] = 1

    def contains(self, item: str) -> bool:
        """Checks if an item is in the Bloom Filter."""
        return all(self.bit_array[hash_value] for hash_value in self._hashes(item))

