import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation that utilizes a modular approach for bit array 
    representation and derives multiple hash functions from a single base hash function 
    to ensure effective probabilistic membership testing.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        """
        Initializes the Bloom Filter instance with calculated parameters for 
        the bit array and number of hash functions based on the provided inputs.

        :param expected_items: Expected number of elements to be stored in the filter.
        :param false_positive_rate: Desired false positive rate. Must be between 0 and 1.
        """
