            raise ValueError("False positive rate must be in (0, 1)")

        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        self.size = self._calculate_optimal_bit_array_size()
        self.hash_count = self._calculate_optimal_hash_count()

        self.bit_array = [0] * self.size

    def _calculate_optimal_bit_array_size(self) -> int:
        """Calculates the optimal size of the bit array."""
        return math.ceil((-self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _calculate_optimal_hash_count(self) -> int:
        """Determines the optimal number of hash functions to use."""
        return math.ceil((self.size / self.expected_items) * math.log(2))

    def _get_hash_indices(self, item: str) -> list:
        """Generates a list of hash indices for the given item using a base hash function."""
        base_hash = int(hashlib.md5(item.encode('utf-8')).hexdigest(), 16)
        return [(base_hash + i) % self.size for i in range(self.hash_count)]

    def add(self, item: str) -> None:
        """Adds an item to the Bloom Filter, setting bits in the bit array."""
        for index in self._get_hash_indices(item):
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Checks whether an item is in the Bloom Filter."""
        return all(self.bit_array[index] for index in self._get_hash_indices(item))
